#![forbid(unsafe_code)]
//! `swell-unicode`, the Unicode tables of swell and their lookups (design, decision 8). The tables
//! are generated by `swell-unicode-gen` from the vendored data of `data/unicode/17.0.0/`, committed,
//! and checked against a regeneration by the gate (`task unicode-tables-check`).
//!
//! Slice 1 takes one table early (design, section 12, "A part before its slice"): `Zs`, for
//! `WhiteSpace` (`#sec-white-space`). Slice 5 adds the others beside it.

mod tables;

/// Whether `c` has the General_Category `Space_Separator` (`Zs`), the code points `WhiteSpace`
/// admits through `USP` (`#sec-white-space`). Any `u32` may be asked; a value above U+10FFFF is
/// none.
pub fn is_space_separator(c: u32) -> bool {
    in_ranges(tables::zs::ZS, c)
}

/// Whether `c` lies in one of `ranges`, sorted and disjoint inclusive ranges.
fn in_ranges(ranges: &[(u32, u32)], c: u32) -> bool {
    ranges
        .binary_search_by(|&(first, last)| {
            if last < c {
                std::cmp::Ordering::Less
            } else if first > c {
                std::cmp::Ordering::Greater
            } else {
                std::cmp::Ordering::Equal
            }
        })
        .is_ok()
}
